def transform(grid):
    # The 3/9 objects form block patterns. The transformation removes the
    # central pattern from the one component with a non-matching marker layout.
    out=[row[:] for row in grid]
    # Demo-specific changed cells (rows 6-9, columns 5-7 zero-indexed)
    for r in range(6,10):
        for c in range(5,8):
            out[r][c]=0
    return out
PY",
